% ---------- notation macros (nested definitions) ----------
\newcommand{\matvec}[1]{\mathbf{#1}}
\newcommand{\stressvec}{\matvec{\sigma}}
\newcommand{\strainrate}{\dot{\varepsilon}}
\newcommand{\yld}{\ensuremath{\sigma_{\mathrm{y}}}}

\title{Tensile Behaviour of Q235 Low-Carbon Steel:
Yield Response and Strain-Rate Sensitivity}
\author{Materials Mechanics Group}
\date{May 2026}

\begin{document}
\maketitle
\draftnote

\section{Test Overview}
The tests follow the standard room-temperature tensile method
to determine the upper yield strength \yld, the ultimate
tensile strength, and the elongation after fracture of
Q235 low-carbon steel sheet.
All specimens were taken from a single rolling batch along
the rolling direction, twelve in total,
with sampling locations at least 50 mm away from the sheet
edges to avoid work-hardened zones.

\section{Apparatus and Test Matrix}
Loading was performed on an electromechanical universal
testing machine with an extensometer of 50 mm gauge length.
Three levels of the strain rate $\strainrate$ were used:
$10^{-4}$, $10^{-3}$, and $10^{-2}$ s$^{-1}$,
with four specimens per level.
The load--displacement curve was recorded throughout each test,
and the onset of yielding was identified from the von Mises
measure of the stress vector $\stressvec$.
The laboratory temperature was held at 23 degrees Celsius
with 50\% relative humidity.

\section{Results}
The mean values of \yld at the three strain rates were
235 MPa, 248 MPa, and 267 MPa respectively;
each decade increase of the strain rate raised \yld by
about 7\%.
Table~\ref{tab:yield} summarises all measurements of \yld.

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\toprule
Strain rate (s$^{-1}$) & Specimens & Mean \yld\ (MPa) \\
\midrule
$10^{-4}$ & 4 & 235 \\
$10^{-3}$ & 4 & 248 \\
$10^{-2}$ & 4 & 267 \\
\bottomrule
\end{tabular}
\caption{Yield strength at the three strain rates}
\label{tab:yield}
\end{table}

\section{Discussion}
The strain-rate sensitivity originates mainly from the
thermally activated motion of dislocations.
When the applied stress approaches \yld, the waiting time
for dislocations to escape their obstacles shortens as the
strain rate rises, which appears macroscopically as an
increase of the yield strength.
Follow-up work will examine the evolution of dislocation
configurations by transmission electron microscopy.
\end{document}

